// BioCanvas Studio — Internationalization & localization layer
export function getLocale() {
  if (typeof document !== 'undefined') {
    const lang = document.documentElement.lang?.toLowerCase() || '';
    if (lang.startsWith('en')) return 'en';
    if (typeof location !== 'undefined' && (location.pathname.includes('/en/') || location.pathname.endsWith('/en'))) return 'en';
  }
  return 'zh';
}

