export function getAssetLabel(asset, locale = getLocale()) {
  if (!asset) return '';
  if (locale === 'en') {
    return asset.labelEn || ASSET_LABELS_EN[asset.id] || asset.name || asset.label || '';
  }
  return asset.label || asset.labelEn || asset.name || '';
}

