export function t(key, locale = getLocale()) {
  return MESSAGES[locale]?.[key] ?? MESSAGES.zh[key] ?? key;
}

// Localize known validation messages at the UI boundary only. Scene content,
// imported labels and machine-readable API error codes remain untouched.
const ERROR_MESSAGES_EN = {
  '不是支持的 BioCanvas 项目文件（v1）。': 'Unsupported BioCanvas project file (v1).',
  '项目中有无效元素。': 'The project contains invalid elements.',
  '元素尺寸无效。': 'Invalid element dimensions.',
  '文字无效。': 'Invalid text.',
  '颜色无效。': 'Invalid color.',
  '素材标识无效。': 'Invalid asset identifier.',
  '连线数据无效。': 'Invalid connector data.',
  '自定义素材无效。': 'Invalid custom asset.',
  '项目标题无效。': 'Invalid project title.',
  'SVG 文件请保持在 2 MB 以内。': 'SVG files must be under 2 MB.',
  '无法读取 SVG 文件。': 'Could not read the SVG file.'
};
export function localizeError(message, locale = getLocale()) {
  let text=String(message);
  if(locale==='en')for(const [source,translation] of Object.entries(ERROR_MESSAGES_EN))text=text.split(source).join(translation);
  return text;
}
